export type AgentSteeringCompletionStatus =
  | "pending"
  | "suspended"
  | "in_progress"
  | "delivered"
  | "discarded"
  | "failed";

export interface AgentSteeringCompletion {
  id: string;
  requesterSessionKey: string;
  status: AgentSteeringCompletionStatus;
  result?: unknown;
  prompt?: string;
  steeringLeaseId?: string;
  steeringLeaseExpiresAt?: number;
  createdAt?: number;
  updatedAt?: number;
  failure?: unknown;
}

export interface AgentSteeringLeaseOptions {
  now?: number;
  leaseId?: string;
  leaseTtlMs?: number;
  limit?: number;
}

export interface AgentSteeringLeaseResult {
  completions: AgentSteeringCompletion[];
  leases: Array<{
    completionId: string;
    leaseId: string;
    requesterSessionKey: string;
    result: unknown;
    prompt: string;
  }>;
}

export interface AgentSteeringAckResult {
  updated: boolean;
  completion?: AgentSteeringCompletion;
}

export interface AgentSteeringReleaseResult {
  updated: boolean;
  completion?: AgentSteeringCompletion;
}

export const DEFAULT_AGENT_STEERING_LEASE_TTL_MS = 5 * 60 * 1000;

const TERMINAL_STATUSES = new Set<AgentSteeringCompletionStatus>([
  "delivered",
  "discarded",
  "failed",
]);

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function resultText(result: unknown): string {
  if (typeof result === "string") return result;
  if (result === undefined || result === null) return "";
  try {
    return JSON.stringify(result);
  } catch {
    return String(result);
  }
}

function completionPrompt(completion: AgentSteeringCompletion): string {
  if (typeof completion.prompt === "string") return completion.prompt;
  const result = resultText(completion.result);
  return result.length > 0 ? result : "Steering completion received.";
}

function randomLeaseId(): string {
  const crypto = (globalThis as { crypto?: { randomUUID?: () => string } }).crypto;
  if (crypto?.randomUUID) return crypto.randomUUID();
  return `steering-${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
}

function isLeaseExpired(completion: AgentSteeringCompletion, now: number): boolean {
  return (
    completion.status === "in_progress" &&
    typeof completion.steeringLeaseExpiresAt === "number" &&
    completion.steeringLeaseExpiresAt <= now
  );
}

/**
 * Lease pending/suspended completions for one requester session.  Lease ownership
 * is represented by steeringLeaseId; an expired in-progress lease is eligible
 * for takeover.
 */
export function leaseAgentSteeringCompletions(
  completions: AgentSteeringCompletion[],
  requesterSessionKey: string,
  options: AgentSteeringLeaseOptions = {},
): AgentSteeringLeaseResult {
  const now = options.now ?? Date.now();
  const ttl = Math.max(1, options.leaseTtlMs ?? DEFAULT_AGENT_STEERING_LEASE_TTL_MS);
  const selected: AgentSteeringLeaseResult["leases"] = [];
  const limit = Math.max(0, options.limit ?? Number.POSITIVE_INFINITY);

  for (const completion of completions) {
    if (selected.length >= limit) break;
    if (completion.requesterSessionKey !== requesterSessionKey) continue;
    if (TERMINAL_STATUSES.has(completion.status)) continue;
    if (completion.status === "in_progress" && !isLeaseExpired(completion, now)) continue;
    if (completion.status !== "pending" && completion.status !== "suspended" && completion.status !== "in_progress") continue;

    const leaseId = options.leaseId ?? randomLeaseId();
    completion.status = "in_progress";
    completion.steeringLeaseId = leaseId;
    completion.steeringLeaseExpiresAt = now + ttl;
    completion.updatedAt = now;
    selected.push({
      completionId: completion.id,
      leaseId,
      requesterSessionKey,
      result: completion.result,
      prompt: completionPrompt(completion),
    });
  }

  return { completions, leases: selected };
}

/** Acknowledge a leased completion.  Only the current, matching lease can ack. */
export function ackAgentSteeringCompletion(
  completions: AgentSteeringCompletion[],
  completionId: string,
  leaseId: string,
): AgentSteeringAckResult {
  const completion = completions.find((item) => item.id === completionId);
  if (!completion) return { updated: false };
  if (completion.status !== "in_progress") return { updated: false };
  if (!completion.steeringLeaseId || completion.steeringLeaseId !== leaseId) {
    return { updated: false };
  }

  completion.status = "delivered";
  completion.steeringLeaseId = undefined;
  completion.steeringLeaseExpiresAt = undefined;
  completion.updatedAt = Date.now();
  return { updated: true, completion };
}

/** Release a failed lease, returning the completion to pending for a later lease. */
export function releaseAgentSteeringCompletion(
  completions: AgentSteeringCompletion[],
  completionId: string,
  leaseId: string,
  failure?: unknown,
): AgentSteeringReleaseResult {
  const completion = completions.find((item) => item.id === completionId);
  if (!completion) return { updated: false };
  if (completion.status !== "in_progress") return { updated: false };
  if (!completion.steeringLeaseId || completion.steeringLeaseId !== leaseId) {
    return { updated: false };
  }

  completion.status = "pending";
  completion.steeringLeaseId = undefined;
  completion.steeringLeaseExpiresAt = undefined;
  completion.failure = failure;
  completion.updatedAt = Date.now();
  return { updated: true, completion };
}

/** A small stateful facade for callers that keep the queue in memory. */
export class AgentSteeringQueue {
  private readonly completions: AgentSteeringCompletion[];

  constructor(completions: AgentSteeringCompletion[] = []) {
    this.completions = completions;
  }

  lease(requesterSessionKey: string, options: AgentSteeringLeaseOptions = {}): AgentSteeringLeaseResult {
    return leaseAgentSteeringCompletions(this.completions, requesterSessionKey, options);
  }

  ack(completionId: string, leaseId: string): AgentSteeringAckResult {
    return ackAgentSteeringCompletion(this.completions, completionId, leaseId);
  }

  release(completionId: string, leaseId: string, failure?: unknown): AgentSteeringReleaseResult {
    return releaseAgentSteeringCompletion(this.completions, completionId, leaseId, failure);
  }

  list(requesterSessionKey?: string): AgentSteeringCompletion[] {
    return this.completions.filter(
      (item) => requesterSessionKey === undefined || item.requesterSessionKey === requesterSessionKey,
    );
  }
}

export function createAgentSteeringQueue(completions: AgentSteeringCompletion[] = []): AgentSteeringQueue {
  return new AgentSteeringQueue(completions);
}

export const leaseAgentSteeringCompletion = leaseAgentSteeringCompletions;

export default AgentSteeringQueue;

